import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector4 } = ctx.THREE;

  // Setup main group
  const mainGroup = new Group();

  // Create cleanup list
  const actives = [];

  // Colors & Styles from spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Dimensions based on atlas region (512x320)
  const width = 2.0;
  const height = width * (320 / 512);

  // STAGE / BACKDROP: Engineered gradient surface with subtle grain mapping
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  // Source Atlas UV calculations
  // Region: 0, 0, 512, 320 on a standard 512x512 or 1024x1024 map if applicable,
  // but as we load the target imagery, we map it.
  const mapUv = uv();

  material.colorNode = vec4(0.043, 0.043, 0.062, 0.95); // Deep surface backdrop #0b0b10

  const cardMesh = new Mesh(geometry, material);
  mainGroup.add(cardMesh);

  // Load ceramic grain texture if available to provide the signature "subtle grain"
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // Text Content rendering (Features 3)
  // Spec typography: "Features 3" (headline, 39px 400). Translate to scene space.
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = textItems.length > 0 ? textItems[0].text : "Features 3";

  // Create typography element via fontAtlas
  const textMesh = ctx.fontAtlas.createText(textString, {
    fontSize: 34, // Map 39px to balanced font atlas size
    color: colors.paper,
    align: 'center'
  });

  // Slightly offset text key on Z to prevent Z-fighting
  textMesh.position.set(0, 0, 0.04);
  mainGroup.add(textMesh);

  // Accent detail line (Engineered aesthetic)
  const lineGeo = new PlaneGeometry(0.3, 0.02);
  const lineMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const lineMesh = new Mesh(lineGeo, lineMat);
  lineMesh.position.set(0, -0.22, 0.03);
  mainGroup.add(lineMesh);

  // Gentle rise-in entry animation (GSAP standard weighted settle)
  mainGroup.position.y -= 0.15;
  mainGroup.scale.set(0.95, 0.95, 0.95);

  const tween = gsap.to(mainGroup, {
    y: 0,
    scale: 1,
    duration: 0.8,
    ease: 'power3.out'
  });
  actives.push(tween);

  // Build handlers and cleanup
  mainGroup.userData = {
    handlers: {},
    cleanup: () => {
      actives.forEach((act) => {
        if (act && typeof act.kill === 'function') act.kill();
      });
      geometry.dispose();
      material.dispose();
      lineGeo.dispose();
      lineMat.dispose();
    }
  };

  return mainGroup;
}
